import sys
from collections import Counter
from math import factorial

MOD = 10**9 + 9

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1

def mod_factorial_inv(n, p):
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % p
    inv_fact[n] = mod_inverse(fact[n], p)
    for i in range(n - 1, 0, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p
    return inv_fact

def count_entirely_unsorted_sequences(n, a):
    count = Counter(a)
    unique_elements = len(count)
    if unique_elements == 1:
        return 0

    total_permutations = factorial(n) % MOD
    for freq in count.values():
        total_permutations = total_permutations * mod_factorial_inv(freq, MOD)[freq] % MOD

    sorted_positions = 0
    for i in range(n):
        is_sorted = True
        for j in range(i):
            if a[j] > a[i]:
                is_sorted = False
                break
        for j in range(i + 1, n):
            if a[j] < a[i]:
                is_sorted = False
                break
        if is_sorted:
            sorted_positions += 1

    if sorted_positions == 0:
        return total_permutations

    return (total_permutations - sorted_positions + MOD) % MOD

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = count_entirely_unsorted_sequences(n, a)
    print(result)

if __name__ == "__main__":
    main()
